-(void) testTrigonometry
{
#define DEGREES_TO_RADIANS(x) ((x) * M_PI / 180.0f)
    
    for (size_t Loop = 0; Loop < 72; Loop += 2)
    {
        const float Values[4] = { DEGREES_TO_RADIANS(Loop * 15), DEGREES_TO_RADIANS(Loop * 15 + 15), DEGREES_TO_RADIANS(Loop * 15 + 5), DEGREES_TO_RADIANS(Loop * 15 + 10) };
        float Result[4];
        
        CCSimdStore_f32x4(Result, CCSimdSin_f32x4(CCSimdLoad_f32x4(Values)));
        
        XCTAssertTrue(CCFloatEqualAbsolute(Result[0], sinf(Values[0]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", sinf(Values[0]), Result[0]);
        XCTAssertTrue(CCFloatEqualAbsolute(Result[1], sinf(Values[1]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", sinf(Values[1]), Result[1]);
        XCTAssertTrue(CCFloatEqualAbsolute(Result[2], sinf(Values[2]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", sinf(Values[2]), Result[2]);
        XCTAssertTrue(CCFloatEqualAbsolute(Result[3], sinf(Values[3]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", sinf(Values[3]), Result[3]);
        
        const float Expected[4] = { asinf(CCClamp(Result[0], 0.0f, 1.0f)), asinf(CCClamp(Result[1], 0.0f, 1.0f)), asinf(CCClamp(Result[2], 0.0f, 1.0f)), asinf(CCClamp(Result[3], 0.0f, 1.0f)) };
        
        CCSimdStore_f32x4(Result, CCSimdArcSin_f32x4(CCSimdClamp_f32x4(CCSimdLoad_f32x4(Result), CCSimdZero_f32x4(), CCSimdFill_f32x4(1.0f))));
        
        XCTAssertTrue(CCFloatEqualAbsolute(Result[0], Expected[0], 0.01f), @"should contain the correct value (approx: %f) instead got: %f", Expected[0], Result[0]);
        XCTAssertTrue(CCFloatEqualAbsolute(Result[1], Expected[1], 0.01f), @"should contain the correct value (approx: %f) instead got: %f", Expected[1], Result[1]);
        XCTAssertTrue(CCFloatEqualAbsolute(Result[2], Expected[2], 0.01f), @"should contain the correct value (approx: %f) instead got: %f", Expected[2], Result[2]);
        XCTAssertTrue(CCFloatEqualAbsolute(Result[3], Expected[3], 0.01f), @"should contain the correct value (approx: %f) instead got: %f", Expected[3], Result[3]);
    }
    
    for (size_t Loop = 0; Loop < 72; Loop += 2)
    {
        const float Values[4] = { -DEGREES_TO_RADIANS(Loop * 15), -DEGREES_TO_RADIANS(Loop * 15 + 15), -DEGREES_TO_RADIANS(Loop * 15 + 5), -DEGREES_TO_RADIANS(Loop * 15 + 10) };
        float Result[4];
        
        CCSimdStore_f32x4(Result, CCSimdSin_f32x4(CCSimdLoad_f32x4(Values)));
        
        XCTAssertTrue(CCFloatEqualAbsolute(Result[0], sinf(Values[0]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", sinf(Values[0]), Result[0]);
        XCTAssertTrue(CCFloatEqualAbsolute(Result[1], sinf(Values[1]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", sinf(Values[1]), Result[1]);
        XCTAssertTrue(CCFloatEqualAbsolute(Result[2], sinf(Values[2]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", sinf(Values[2]), Result[2]);
        XCTAssertTrue(CCFloatEqualAbsolute(Result[3], sinf(Values[3]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", sinf(Values[3]), Result[3]);
        
