        XCTAssertEqual(Result[0], (uint64_t)(Values[0] << Loop) | (Values[0] >> (-Loop & 63)), @"should contain the correct value");
        XCTAssertEqual(Result[1], (uint64_t)(Values[1] << Loop) | (Values[1] >> (-Loop & 63)), @"should contain the correct value");
    }
    
    for (size_t Loop = 0; Loop < 64; Loop++)
    {
        const uint64_t Values[4] = { 1, -2 };
        uint64_t Result[4];
        
        CCSimdStore_u64x2(Result, CCSimdRotateRightN_u64x2(CCSimdLoad_u64x2(Values), Loop));
        
        XCTAssertEqual(Result[0], (Values[0] >> Loop) | (uint64_t)(Values[0] << (-Loop & 63)), @"should contain the correct value");
        XCTAssertEqual(Result[1], (Values[1] >> Loop) | (uint64_t)(Values[1] << (-Loop & 63)), @"should contain the correct value");
    }
}

-(void) testBitMaths
{
    for (size_t Loop = 0; Loop < 7; Loop++)
    {
        const int8_t Values[16] = { 1 << Loop, (1 << Loop) + 1, (1 << Loop) + 3, (1 << Loop) + 240, (1 << Loop) + 5, (1 << Loop) + 6, (1 << Loop) + 7, (1 << Loop) + 9, (1 << Loop) + 9, (1 << Loop) + 7, (1 << Loop) + 6, (1 << Loop) + 5, (1 << Loop) + 240, (1 << Loop) + 3, (1 << Loop) + 1, 1 << Loop };
        int8_t Result[16];
        
        CCSimdStore_s8x16(Result, CCSimdLowestUnset_s8x16(CCSimdLoad_s8x16(Values)));
        XCTAssertEqual(Result[0], CCBitLowestUnset(Values[0]), @"should contain the correct value");
        XCTAssertEqual(Result[1], CCBitLowestUnset(Values[1]), @"should contain the correct value");
        XCTAssertEqual(Result[2], CCBitLowestUnset(Values[2]), @"should contain the correct value");
        XCTAssertEqual(Result[3], CCBitLowestUnset(Values[3]), @"should contain the correct value");
        XCTAssertEqual(Result[4], CCBitLowestUnset(Values[4]), @"should contain the correct value");
        XCTAssertEqual(Result[5], CCBitLowestUnset(Values[5]), @"should contain the correct value");
        XCTAssertEqual(Result[6], CCBitLowestUnset(Values[6]), @"should contain the correct value");
        XCTAssertEqual(Result[7], CCBitLowestUnset(Values[7]), @"should contain the correct value");
