-(void) testMathFunctions
{
    const float Values_f32[4] = { -2.0f, -5.0f, -2.5f, -1.5f };
    float Result_f32[4];
    
    CCSimdStore_f32x4(Result_f32, CCSimdExp_f32x4(CCSimdLoad_f32x4(Values_f32)));
    
    XCTAssertTrue((isinf(Result_f32[0]) && isinf(Values_f32[0])) || CCFloatEqualAbsolute(Result_f32[0], expf(Values_f32[0]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", expf(Values_f32[0]), Result_f32[0]);
    XCTAssertTrue((isinf(Result_f32[1]) && isinf(Values_f32[1])) || CCFloatEqualAbsolute(Result_f32[1], expf(Values_f32[1]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", expf(Values_f32[1]), Result_f32[1]);
    XCTAssertTrue((isinf(Result_f32[2]) && isinf(Values_f32[2])) || CCFloatEqualAbsolute(Result_f32[2], expf(Values_f32[2]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", expf(Values_f32[2]), Result_f32[2]);
    XCTAssertTrue((isinf(Result_f32[3]) && isinf(Values_f32[3])) || CCFloatEqualAbsolute(Result_f32[3], expf(Values_f32[3]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", expf(Values_f32[3]), Result_f32[3]);
    
    for (size_t Loop = 0; Loop < 44; Loop += 2)
    {
        const float Values_f32[4] = { 0.000000000001f * powf(2.0f, Loop), 0.0000000000015f * powf(2.0f, Loop), 0.000000000003f * powf(2.0f, Loop), 0.000000000005f * powf(2.0f, Loop) };
        float Result_f32[4];
        
        CCSimdStore_f32x4(Result_f32, CCSimdExp_f32x4(CCSimdLoad_f32x4(Values_f32)));
        
        XCTAssertTrue((isinf(Result_f32[0]) && isinf(Values_f32[0])) || CCFloatEqualAbsolute(Result_f32[0], expf(Values_f32[0]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", expf(Values_f32[0]), Result_f32[0]);
        XCTAssertTrue((isinf(Result_f32[1]) && isinf(Values_f32[1])) || CCFloatEqualAbsolute(Result_f32[1], expf(Values_f32[1]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", expf(Values_f32[1]), Result_f32[1]);
        XCTAssertTrue((isinf(Result_f32[2]) && isinf(Values_f32[2])) || CCFloatEqualAbsolute(Result_f32[2], expf(Values_f32[2]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", expf(Values_f32[2]), Result_f32[2]);
        XCTAssertTrue((isinf(Result_f32[3]) && isinf(Values_f32[3])) || CCFloatEqualAbsolute(Result_f32[3], expf(Values_f32[3]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", expf(Values_f32[3]), Result_f32[3]);
    }
    
    
    CCSimdStore_f32x4(Result_f32, CCSimdExp2_f32x4(CCSimdLoad_f32x4(Values_f32)));
    
    XCTAssertTrue((isinf(Result_f32[0]) && isinf(Values_f32[0])) || CCFloatEqualAbsolute(Result_f32[0], exp2f(Values_f32[0]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", exp2f(Values_f32[0]), Result_f32[0]);
    XCTAssertTrue((isinf(Result_f32[1]) && isinf(Values_f32[1])) || CCFloatEqualAbsolute(Result_f32[1], exp2f(Values_f32[1]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", exp2f(Values_f32[1]), Result_f32[1]);
    XCTAssertTrue((isinf(Result_f32[2]) && isinf(Values_f32[2])) || CCFloatEqualAbsolute(Result_f32[2], exp2f(Values_f32[2]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", exp2f(Values_f32[2]), Result_f32[2]);
    XCTAssertTrue((isinf(Result_f32[3]) && isinf(Values_f32[3])) || CCFloatEqualAbsolute(Result_f32[3], exp2f(Values_f32[3]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", exp2f(Values_f32[3]), Result_f32[3]);
    
    for (size_t Loop = 0; Loop < 44; Loop += 2)
    {
        const float Values_f32[4] = { 0.000000000001f * powf(2.0f, Loop), 0.0000000000015f * powf(2.0f, Loop), 0.0000000000003f * powf(2.0f, Loop), 0.0000000000005f * powf(2.0f, Loop) };
        float Result_f32[4];
        
        CCSimdStore_f32x4(Result_f32, CCSimdExp2_f32x4(CCSimdLoad_f32x4(Values_f32)));
        
        XCTAssertTrue((isinf(Result_f32[0]) && isinf(Values_f32[0])) || CCFloatEqualAbsolute(Result_f32[0], exp2f(Values_f32[0]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", exp2f(Values_f32[0]), Result_f32[0]);
        XCTAssertTrue((isinf(Result_f32[1]) && isinf(Values_f32[1])) || CCFloatEqualAbsolute(Result_f32[1], exp2f(Values_f32[1]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", exp2f(Values_f32[1]), Result_f32[1]);
        XCTAssertTrue((isinf(Result_f32[2]) && isinf(Values_f32[2])) || CCFloatEqualAbsolute(Result_f32[2], exp2f(Values_f32[2]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", exp2f(Values_f32[2]), Result_f32[2]);
        XCTAssertTrue((isinf(Result_f32[3]) && isinf(Values_f32[3])) || CCFloatEqualAbsolute(Result_f32[3], exp2f(Values_f32[3]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", exp2f(Values_f32[3]), Result_f32[3]);
    }
    
    
    for (size_t Loop = 0; Loop < 44; Loop += 2)
    {
        const float Values_f32[4] = { 0.000000000001f * powf(2.0f, Loop), 0.0000000000015f * powf(2.0f, Loop), 0.000000000003f * powf(2.0f, Loop), 0.000000000005f * powf(2.0f, Loop) };
        float Result_f32[4];
        
        CCSimdStore_f32x4(Result_f32, CCSimdLog_f32x4(CCSimdLoad_f32x4(Values_f32)));
        
        XCTAssertTrue((isinf(Result_f32[0]) && isinf(Values_f32[0])) || CCFloatEqualAbsolute(Result_f32[0], logf(Values_f32[0]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", logf(Values_f32[0]), Result_f32[0]);
        XCTAssertTrue((isinf(Result_f32[1]) && isinf(Values_f32[1])) || CCFloatEqualAbsolute(Result_f32[1], logf(Values_f32[1]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", logf(Values_f32[1]), Result_f32[1]);
        XCTAssertTrue((isinf(Result_f32[2]) && isinf(Values_f32[2])) || CCFloatEqualAbsolute(Result_f32[2], logf(Values_f32[2]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", logf(Values_f32[2]), Result_f32[2]);
        XCTAssertTrue((isinf(Result_f32[3]) && isinf(Values_f32[3])) || CCFloatEqualAbsolute(Result_f32[3], logf(Values_f32[3]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", logf(Values_f32[3]), Result_f32[3]);
    }
    
    
    for (size_t Loop = 0; Loop < 44; Loop += 2)
    {
        const float Values_f32[4] = { 0.000000000001f * powf(2.0f, Loop), 0.0000000000015f * powf(2.0f, Loop), 0.000000000003f * powf(2.0f, Loop), 0.000000000005f * powf(2.0f, Loop) };
        float Result_f32[4];
        
        CCSimdStore_f32x4(Result_f32, CCSimdLog2_f32x4(CCSimdLoad_f32x4(Values_f32)));
        
        XCTAssertTrue((isinf(Result_f32[0]) && isinf(Values_f32[0])) || CCFloatEqualAbsolute(Result_f32[0], log2f(Values_f32[0]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", log2f(Values_f32[0]), Result_f32[0]);
        XCTAssertTrue((isinf(Result_f32[1]) && isinf(Values_f32[1])) || CCFloatEqualAbsolute(Result_f32[1], log2f(Values_f32[1]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", log2f(Values_f32[1]), Result_f32[1]);
        XCTAssertTrue((isinf(Result_f32[2]) && isinf(Values_f32[2])) || CCFloatEqualAbsolute(Result_f32[2], log2f(Values_f32[2]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", log2f(Values_f32[2]), Result_f32[2]);
        XCTAssertTrue((isinf(Result_f32[3]) && isinf(Values_f32[3])) || CCFloatEqualAbsolute(Result_f32[3], log2f(Values_f32[3]), 0.01f), @"should contain the correct value (approx: %f) instead got: %f", log2f(Values_f32[3]), Result_f32[3]);
    }
    
    
