-(void) testArithmetic
{
    int64_t Result_s64[2];
    const CCSimd_s64x2 VecA_s64x2 = CCSimdLoad_s64x2((int64_t[2]){ 10, 11 });
    const CCSimd_s64x2 VecB_s64x2 = CCSimdLoad_s64x2((int64_t[2]){ 2, 4 });
    const CCSimd_s64x2 VecC_s64x2 = CCSimdLoad_s64x2((int64_t[2]){ 5, 6 });
    
    CCSimdStore_s64x2(Result_s64, CCSimdAdd_s64x2(VecA_s64x2, VecB_s64x2));
    XCTAssertEqual(Result_s64[0], 12, @"should contain the correct value");
    XCTAssertEqual(Result_s64[1], 15, @"should contain the correct value");
    
    CCSimdStore_s64x2(Result_s64, CCSimdSub_s64x2(VecA_s64x2, VecB_s64x2));
    XCTAssertEqual(Result_s64[0], 8, @"should contain the correct value");
    XCTAssertEqual(Result_s64[1], 7, @"should contain the correct value");
    
    CCSimdStore_s64x2(Result_s64, CCSimdMul_s64x2(VecA_s64x2, VecB_s64x2));
    XCTAssertEqual(Result_s64[0], 20, @"should contain the correct value");
    XCTAssertEqual(Result_s64[1], 44, @"should contain the correct value");
    
    CCSimdStore_s64x2(Result_s64, CCSimdMadd_s64x2(VecA_s64x2, VecB_s64x2, VecC_s64x2));
    XCTAssertEqual(Result_s64[0], 25, @"should contain the correct value");
    XCTAssertEqual(Result_s64[1], 50, @"should contain the correct value");
    
    CCSimdStore_s64x2(Result_s64, CCSimdMsub_s64x2(VecA_s64x2, VecB_s64x2, VecC_s64x2));
    XCTAssertEqual(Result_s64[0], 15, @"should contain the correct value");
    XCTAssertEqual(Result_s64[1], 38, @"should contain the correct value");
    
    CCSimdStore_s64x2(Result_s64, CCSimdNegMadd_s64x2(VecA_s64x2, VecB_s64x2, VecC_s64x2));
    XCTAssertEqual(Result_s64[0], -15, @"should contain the correct value");
    XCTAssertEqual(Result_s64[1], -38, @"should contain the correct value");
    
    CCSimdStore_s64x2(Result_s64, CCSimdNegMsub_s64x2(VecA_s64x2, VecB_s64x2, VecC_s64x2));
    XCTAssertEqual(Result_s64[0], -25, @"should contain the correct value");
    XCTAssertEqual(Result_s64[1], -50, @"should contain the correct value");
    
    CCSimdStore_s64x2(Result_s64, CCSimdDiv_s64x2(VecA_s64x2, VecB_s64x2));
    XCTAssertEqual(Result_s64[0], 5, @"should contain the correct value");
    XCTAssertEqual(Result_s64[1], 2, @"should contain the correct value");
    
    CCSimdStore_s64x2(Result_s64, CCSimdMod_s64x2(VecA_s64x2, VecB_s64x2));
    XCTAssertEqual(Result_s64[0], 0, @"should contain the correct value");
    XCTAssertEqual(Result_s64[1], 3, @"should contain the correct value");
    
    XCTAssertEqual(CCSimdSum_s64x2(VecA_s64x2), 21, @"should contain the correct value");
    
    CCSimdStore_s64x2(Result_s64, CCSimdNeg_s64x2(VecA_s64x2));
    XCTAssertEqual(Result_s64[0], -10, @"should contain the correct value");
    XCTAssertEqual(Result_s64[1], -11, @"should contain the correct value");
    
    CCSimdStore_s64x2(Result_s64, CCSimdMin_s64x2(VecA_s64x2, VecB_s64x2));
    XCTAssertEqual(Result_s64[0], 2, @"should contain the correct value");
    XCTAssertEqual(Result_s64[1], 4, @"should contain the correct value");
    
    CCSimdStore_s64x2(Result_s64, CCSimdMax_s64x2(VecA_s64x2, VecB_s64x2));
    XCTAssertEqual(Result_s64[0], 10, @"should contain the correct value");
    XCTAssertEqual(Result_s64[1], 11, @"should contain the correct value");
    
    CCSimdStore_s64x2(Result_s64, CCSimdClamp_s64x2(VecA_s64x2, VecB_s64x2, VecC_s64x2));
    XCTAssertEqual(Result_s64[0], 5, @"should contain the correct value");
    XCTAssertEqual(Result_s64[1], 6, @"should contain the correct value");
    
    
    uint64_t Result_u64[2];
    const CCSimd_u64x2 VecA_u64x2 = CCSimdLoad_u64x2((uint64_t[2]){ 10, 11 });
    const CCSimd_u64x2 VecB_u64x2 = CCSimdLoad_u64x2((uint64_t[2]){ 2, 4 });
    const CCSimd_u64x2 VecC_u64x2 = CCSimdLoad_u64x2((uint64_t[2]){ 5, 6 });

    CCSimdStore_u64x2(Result_u64, CCSimdAdd_u64x2(VecA_u64x2, VecB_u64x2));
    XCTAssertEqual(Result_u64[0], 12, @"should contain the correct value");
    XCTAssertEqual(Result_u64[1], 15, @"should contain the correct value");

    CCSimdStore_u64x2(Result_u64, CCSimdSub_u64x2(VecA_u64x2, VecB_u64x2));
    XCTAssertEqual(Result_u64[0], 8, @"should contain the correct value");
    XCTAssertEqual(Result_u64[1], 7, @"should contain the correct value");

    CCSimdStore_u64x2(Result_u64, CCSimdMul_u64x2(VecA_u64x2, VecB_u64x2));
    XCTAssertEqual(Result_u64[0], 20, @"should contain the correct value");
    XCTAssertEqual(Result_u64[1], 44, @"should contain the correct value");

    CCSimdStore_u64x2(Result_u64, CCSimdMadd_u64x2(VecA_u64x2, VecB_u64x2, VecC_u64x2));
    XCTAssertEqual(Result_u64[0], 25, @"should contain the correct value");
    XCTAssertEqual(Result_u64[1], 50, @"should contain the correct value");

    CCSimdStore_u64x2(Result_u64, CCSimdMsub_u64x2(VecA_u64x2, VecB_u64x2, VecC_u64x2));
    XCTAssertEqual(Result_u64[0], 15, @"should contain the correct value");
    XCTAssertEqual(Result_u64[1], 38, @"should contain the correct value");

    CCSimdStore_u64x2(Result_u64, CCSimdNegMadd_u64x2(VecA_u64x2, VecB_u64x2, VecC_u64x2));
    XCTAssertEqual(Result_u64[0], -15, @"should contain the correct value");
    XCTAssertEqual(Result_u64[1], -38, @"should contain the correct value");

    CCSimdStore_u64x2(Result_u64, CCSimdNegMsub_u64x2(VecA_u64x2, VecB_u64x2, VecC_u64x2));
    XCTAssertEqual(Result_u64[0], -25, @"should contain the correct value");
    XCTAssertEqual(Result_u64[1], -50, @"should contain the correct value");

    CCSimdStore_u64x2(Result_u64, CCSimdDiv_u64x2(VecA_u64x2, VecB_u64x2));
    XCTAssertEqual(Result_u64[0], 5, @"should contain the correct value");
    XCTAssertEqual(Result_u64[1], 2, @"should contain the correct value");

    CCSimdStore_u64x2(Result_u64, CCSimdMod_u64x2(VecA_u64x2, VecB_u64x2));
    XCTAssertEqual(Result_u64[0], 0, @"should contain the correct value");
    XCTAssertEqual(Result_u64[1], 3, @"should contain the correct value");

    XCTAssertEqual(CCSimdSum_u64x2(VecA_u64x2), 21, @"should contain the correct value");

    CCSimdStore_u64x2(Result_u64, CCSimdNeg_u64x2(VecA_u64x2));
    XCTAssertEqual(Result_u64[0], -10, @"should contain the correct value");
    XCTAssertEqual(Result_u64[1], -11, @"should contain the correct value");

    CCSimdStore_u64x2(Result_u64, CCSimdMin_u64x2(VecA_u64x2, VecB_u64x2));
    XCTAssertEqual(Result_u64[0], 2, @"should contain the correct value");
    XCTAssertEqual(Result_u64[1], 4, @"should contain the correct value");

    CCSimdStore_u64x2(Result_u64, CCSimdMax_u64x2(VecA_u64x2, VecB_u64x2));
    XCTAssertEqual(Result_u64[0], 10, @"should contain the correct value");
    XCTAssertEqual(Result_u64[1], 11, @"should contain the correct value");

    CCSimdStore_u64x2(Result_u64, CCSimdClamp_u64x2(VecA_u64x2, VecB_u64x2, VecC_u64x2));
    XCTAssertEqual(Result_u64[0], 5, @"should contain the correct value");
    XCTAssertEqual(Result_u64[1], 6, @"should contain the correct value");
    
    
    double Result_f64[2];
    const CCSimd_f64x2 VecA_f64x2 = CCSimdLoad_f64x2((double[2]){ 10.0, 11.0 });
    const CCSimd_f64x2 VecB_f64x2 = CCSimdLoad_f64x2((double[2]){ 2.0, 4.0 });
    const CCSimd_f64x2 VecC_f64x2 = CCSimdLoad_f64x2((double[2]){ 5.0, 6.0 });
    
    CCSimdStore_f64x2(Result_f64, CCSimdAdd_f64x2(VecA_f64x2, VecB_f64x2));
    XCTAssertEqual(Result_f64[0], 12.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], 15.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdSub_f64x2(VecA_f64x2, VecB_f64x2));
    XCTAssertEqual(Result_f64[0], 8.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], 7.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdMul_f64x2(VecA_f64x2, VecB_f64x2));
    XCTAssertEqual(Result_f64[0], 20.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], 44.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdMadd_f64x2(VecA_f64x2, VecB_f64x2, VecC_f64x2));
    XCTAssertEqual(Result_f64[0], 25.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], 50.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdMsub_f64x2(VecA_f64x2, VecB_f64x2, VecC_f64x2));
    XCTAssertEqual(Result_f64[0], 15.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], 38.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdNegMadd_f64x2(VecA_f64x2, VecB_f64x2, VecC_f64x2));
    XCTAssertEqual(Result_f64[0], -15.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], -38.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdNegMsub_f64x2(VecA_f64x2, VecB_f64x2, VecC_f64x2));
    XCTAssertEqual(Result_f64[0], -25.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], -50.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdDiv_f64x2(VecA_f64x2, VecB_f64x2));
    XCTAssertEqual(Result_f64[0], 5.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], 2.75f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdMod_f64x2(VecA_f64x2, VecB_f64x2));
    XCTAssertEqual(Result_f64[0], 0.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], 3.0f, @"should contain the correct value");
    
    XCTAssertEqual(CCSimdSum_f64x2(VecA_f64x2), 21.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdNeg_f64x2(VecA_f64x2));
    XCTAssertEqual(Result_f64[0], -10, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], -11, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdMin_f64x2(VecA_f64x2, VecB_f64x2));
    XCTAssertEqual(Result_f64[0], 2.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], 4.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdMax_f64x2(VecA_f64x2, VecB_f64x2));
    XCTAssertEqual(Result_f64[0], 10.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], 11.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdClamp_f64x2(VecA_f64x2, VecB_f64x2, VecC_f64x2));
    XCTAssertEqual(Result_f64[0], 5.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], 6.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdSqrt_f64x2(VecA_f64x2));
    XCTAssertTrue(CCFloatEqualAbsolute(Result_f64[0], sqrt(10.0), 0.01f), @"should contain the correct value");
    XCTAssertTrue(CCFloatEqualAbsolute(Result_f64[1], sqrt(11.0), 0.01f), @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdInvSqrt_f64x2(VecA_f64x2));
    XCTAssertTrue(CCFloatEqualAbsolute(Result_f64[0], 1.0 / sqrt(10.0), 0.01f), @"should contain the correct value");
    XCTAssertTrue(CCFloatEqualAbsolute(Result_f64[1], 1.0 / sqrt(11.0), 0.01f), @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdCbrt_f64x2(VecA_f64x2));
    XCTAssertTrue(CCFloatEqualAbsolute(Result_f64[0], cbrt(10.0), 0.01f), @"should contain the correct value");
    XCTAssertTrue(CCFloatEqualAbsolute(Result_f64[1], cbrt(11.0), 0.01f), @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdInvCbrt_f64x2(VecA_f64x2));
    XCTAssertTrue(CCFloatEqualAbsolute(Result_f64[0], 1.0 / cbrt(10.0), 0.01f), @"should contain the correct value");
    XCTAssertTrue(CCFloatEqualAbsolute(Result_f64[1], 1.0 / cbrt(11.0), 0.01f), @"should contain the correct value");
    
    const CCSimd_f64x2 VecPos_f64x2 = CCSimdLoad_f64x2((double[2]){ 10.5f, 11.5f });
    
    CCSimdStore_f64x2(Result_f64, CCSimdRoundNearestAway_f64x2(VecPos_f64x2));
    XCTAssertEqual(Result_f64[0], 11.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], 12.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdRoundNearestEven_f64x2(VecPos_f64x2));
    XCTAssertEqual(Result_f64[0], 10.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], 12.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdRoundZero_f64x2(VecPos_f64x2));
    XCTAssertEqual(Result_f64[0], 10.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], 11.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdFloor_f64x2(VecPos_f64x2));
    XCTAssertEqual(Result_f64[0], 10.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], 11.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdCeil_f64x2(VecPos_f64x2));
    XCTAssertEqual(Result_f64[0], 11.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], 12.0f, @"should contain the correct value");
    
    const CCSimd_f64x2 VecNeg_f64x2 = CCSimdLoad_f64x2((double[2]){ -10.5f, -11.5f });
    
    CCSimdStore_f64x2(Result_f64, CCSimdRoundNearestAway_f64x2(VecNeg_f64x2));
    XCTAssertEqual(Result_f64[0], -11.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], -12.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdRoundNearestEven_f64x2(VecNeg_f64x2));
    XCTAssertEqual(Result_f64[0], -10.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], -12.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdRoundZero_f64x2(VecNeg_f64x2));
    XCTAssertEqual(Result_f64[0], -10.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], -11.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdFloor_f64x2(VecNeg_f64x2));
    XCTAssertEqual(Result_f64[0], -11.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], -12.0f, @"should contain the correct value");
    
    CCSimdStore_f64x2(Result_f64, CCSimdCeil_f64x2(VecNeg_f64x2));
    XCTAssertEqual(Result_f64[0], -10.0f, @"should contain the correct value");
    XCTAssertEqual(Result_f64[1], -11.0f, @"should contain the correct value");
}

